/**
 * Unit tests for StrBuilder.indexOf(String str, int startIndex)
 * Designed to maximize branch and line coverage.
 */
public class StrBuilder_indexOf_TriageGen0Test {



    @Test
    public void testIndexOf_StartIndexLogic() {
        StrBuilder sb = new StrBuilder("abcabc");
        // startIndex < 0 should be treated as 0
        Assert.assertEquals(0, sb.indexOf("abc", -5));
        // startIndex at match point
        Assert.assertEquals(3, sb.indexOf("abc", 3));
        // startIndex >= size should return -1
        Assert.assertEquals(-1, sb.indexOf("abc", 6));
        Assert.assertEquals(-1, sb.indexOf("abc", 10));
    }












}

