public class StrBuilder_indexOf_TriageGen0Test {













    @Test
    public void testIndexOf_BoundaryConditions() {
        StrBuilder sb = new StrBuilder("test");
        // Search for full string
        Assert.assertEquals(0, sb.indexOf("test", 0));
        // Search for string at the very end of the buffer
        StrBuilder sb2 = new StrBuilder("abc");
        Assert.assertEquals(2, sb2.indexOf("c", 0));
        // Search for string that matches last possible position
        Assert.assertEquals(0, sb2.indexOf("abc", 0));
    }


